#include <bits/stdc++.h>
using namespace std;

const long long M1=998244353, M2=1000000007;

long long counter=0, n_value, low_sum, total_answer=0, pow10[8];
vector<int> num_list[7];

void build_numbers(int depth, int val)
{
    int temp=(counter+M1-val)%M1;
    num_list[depth].push_back(temp);
    low_sum=(low_sum+temp)%M2;
    counter++;
    if(depth<6)
    {
        for(int digit=0; digit<10; ++digit)
            build_numbers(depth+1, val*10+digit);
    }
}

void compute(int depth, long long x)
{
    if(x>n_value) return;
    int i;
    if(x*pow10[6]+pow10[6]-1<=n_value && x*pow10[7]>n_value)
    {
        for(i=0;i<=6;i++)
        {
            long long delta=(counter+(M1-pow10[i])*x)%M1;
            total_answer=(total_answer+(delta+M2-M1)*pow10[i]+M1*(lower_bound(num_list[i].begin(),num_list[i].end(),M1-delta)-num_list[i].begin()))%M2;
        }
        total_answer=(total_answer+low_sum)%M2;
        counter+=1111111;
        return;
    }
    total_answer=(total_answer+(counter+M1-x%M1)%M1)%M2;
    counter++;
    for(i=depth?0:1;i<10;i++) compute(depth+1,x*10+i);
}

int main()
{
    int i;
    pow10[0]=1;
    for(i=1;i<=7;i++) pow10[i]=pow10[i-1]*10;
    build_numbers(0,0);
    for(i=1;i<=6;i++) sort(num_list[i].begin(),num_list[i].end());
    cin>>n_value;
    counter=0;
    compute(0,0);
    cout<<total_answer<<endl;
    return 0;
}
